import {
  Disclosure,
  DisclosureButton,
  DisclosurePanel,
  Menu,
  MenuButton,
  MenuItem,
  MenuItems,
} from "@headlessui/react";
import { UserCircleIcon } from "@heroicons/react/24/outline";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import { Diamond, PlusCircleIcon } from "lucide-react";
import FormModal from "../form/FormModal";
import { Dialog, DialogBackdrop, DialogPanel, DialogTitle } from "@headlessui/react";

const API_URL = process.env.REACT_APP_API_BASE_URL;
const CLIENT_BASE_URL = process.env.REACT_APP_BASE_URL || "";
const getCSRFToken = () => {
  const match = document.cookie.match(/csrf_access_token=([^;]+)/);
  return match ? match[1] : null;
};

function useQuery() {
  return new URLSearchParams(useLocation().search);
}

export function HomePage() {
  const baseURL = process.env.REACT_APP_BASE_URL || "";
  const [credits, setCredits] = useState(null);
  const [feedbackIds, setFeedbackIds] = useState([]);
  const [selectedNav, setSelectedNav] = useState(0);
  // New session modal state
  const [showSessionModal, setShowSessionModal] = useState(false);
  const navItems = ["Home"];
  const query = useQuery();
  const navigate = useNavigate();

  //States for modal
  const [showModal, setShowModal] = useState(false);
  const [modalFields, setModalFields] = useState([]);
  const [modalHeading, setModalHeading] = useState("");
  const [modalSubheading, setModalSubheading] = useState("");
  const [modalClosingHeading, setModalClosingHeading] = useState("");
  const [modalClosingMessage, setModalClosingMessage] = useState("");
  const [modalLoading, setModalLoading] = useState(false);
  const [modalSubmitted, setModalSubmitted] = useState(false);

  useEffect(() => {
    const csrfToken = getCSRFToken();
    const orderID = query.get("token");

    if (orderID) {
      fetch(`${API_URL}/capture_order`, {
        method: "POST",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
          "X-CSRF-Token": csrfToken,
        },
        body: JSON.stringify({ orderID }),
      })
        .then(async (res) => {
          if (res.ok) {
            alert("Payment received! Credits will be updated soon.");
          } else {
            const data = await res.json();
            alert(
              "Payment processing failed: " + (data?.error || res.statusText)
            );
          }
          navigate(`${baseURL}/`, { replace: true });
        })
        .catch((err) => {
          alert("Payment capture failed: " + err.message);
          navigate(`${baseURL}/login`, { replace: true });
        });
    }
    if (!csrfToken) {

      navigate(`${baseURL}/about`, { replace: true });
      return;
    }

    const fetchFormModal = async () => {
      try {
        const csrfToken = getCSRFToken();
        const res = await fetch(`${API_URL}/form_fields?type=welcome`, {
          method: "GET",
          credentials: "include",
          headers: {
            "Content-Type": "application/json",
            "X-CSRF-Token": csrfToken,
          },
        });
        if (res.ok) {
          const data = await res.json();
          if (data.claimed) {
            return;
          }
          setModalFields(data.fields || []);
          setModalHeading(data.heading || "");
          setModalSubheading(data.subheading || "");
          setModalClosingHeading(data.closing_heading || "");
          setModalClosingMessage(data.closing_message || "");
          setShowModal(true);
        }
      } catch (err) {
        console.error("Error fetching form modal data:", err);
      }
    };

    // Call this only if you want to show the modal (e.g., first-time user)
    fetchFormModal();

    const fetchCredits = async () => {
      try {
        const res = await fetch(`${API_URL}/me`, {
          credentials: "include",
          headers: {
            "Content-Type": "application/json",
            "X-CSRF-Token": csrfToken,
          },
        });
        const data = await res.json();
        if (res.ok) {
          setCredits(data.credits);
        } else {
          navigate(`${baseURL}/login`, { replace: true });
        }
      } catch (err) {
        navigate(`${baseURL}/login`, { replace: true });
      }
    };

    const fetchFeedbackIds = async () => {
      try {
        const res = await fetch(`${API_URL}/get_user_feedback_ids`, {
          method: "GET",
          credentials: "include",
          headers: {
            "Content-Type": "application/json",
          },
        });
        if (!res.ok) {
          const data = await res.json();
          console.error("Error fetching feedback IDs:", data);
          return;
        }
        const data = await res.json();
        setFeedbackIds(data);
      } catch (err) {
        console.error("Fetch failed:", err);
      }
    };
    fetchFeedbackIds();
    fetchCredits();
  }, []);

  const handleFormSubmit = async (formData) => {
    setModalLoading(true);
    try {
      const csrfToken = getCSRFToken();
      const res = await fetch(`${API_URL}/submit_form`, {
        method: "POST",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
          "X-CSRF-Token": csrfToken,
        },
        body: JSON.stringify({ responses: formData, formType: "welcome" }),
      });

      if (res.ok) {
        setModalSubmitted(true);
        const data = await res.json();
        setModalClosingHeading(data.heading || "Form submitted");
        setModalClosingMessage(data.body || "Thank you for your feedback!");
        setCredits(data.credits || 0); // Update credits from response
        console.log("Form submitted successfully");
        // Optionally update credits or user state here
      }else if(res.status === 400) {
        const data = await res.json();
        setModalSubmitted(true);
        setModalClosingHeading("Error");
        setModalClosingMessage(data.message || "An error occurred while submitting the form.");
      }
    } catch (err) {
      console.log("Error submitting form:", err);
    }
    setModalLoading(false);
  };

  // Sign out function
  async function handleSignOut(e) {
    e.preventDefault();
    try {
      await fetch(`${API_URL}/logout`, {
        method: "POST",
        credentials: "include",
      });
      navigate(`${baseURL}/login`);
    } catch (err) {
      console.error("Logout failed", err);
    }
  }
  return (
    <>
      {modalFields ? (
        <FormModal
          open={showModal}
          onClose={() => setShowModal(false)}
          fields={modalFields}
          heading={modalHeading}
          subheading={modalSubheading}
          closing_heading={modalClosingHeading}
          closing_message={modalClosingMessage}
          onSubmit={handleFormSubmit}
          loading={modalLoading}
          submitted={modalSubmitted}
        />
      ) : null}
      <div className="min-h-screen bg-gray-950 text-gray-200 py-7">
        <div className="w-max mx-auto bg-gray-950 px-1 py-1 text-sm rounded-full shadow-[0_3px_28px] shadow-lime-600/80">
          <div className="flex items-center justify-between mx-auto px-0.5 py-0.5 max-w-fit gap-8">
            <div className="flex items-center justify-center">
              {navItems.map((item, index) => (
                <a
                  key={index}
                  href="#"
                  className={`mx-auto px-2 py-1 cursor-pointer rounded-full text-lg text-center  transition duration-200 ${
                    selectedNav === index
                      ? "text-lime-400 bg-lime-900/70"
                      : "text-lime-400 bg-gray-950"
                  }`}
                  onClick={() => setSelectedNav(index)}
                >
                  {item}
                </a>
              ))}
            </div>
            <Link
              className="px-1 py-1 opacity-100 tracking-wide bg-gradient-to-r from-lime-400 from-30% via-lime-500 to-95% to-lime-400 text-xl bg-clip-text text-transparent font-bold transition duration-200"
              to={`${CLIENT_BASE_URL}/about`}
            >
              ReflectlyAI
            </Link>
            <div className="justify-center hidden md:flex items-center gap-2">
              <Menu
                as="div"
                className="relative flex items-center gap-2 text-left"
              >
                <Diamond className="h-6 w-6 text-lime-500" />
                <h1 className="text-lime-500">{credits ? credits : 0}</h1>
                <MenuButton className="flex ms-2 items-center gap-2 focus:outline-none">
                  <UserCircleIcon className="h-8 w-8 text-lime-500 cursor-pointer" />
                </MenuButton>
                <MenuItems className="absolute top-full right-0 mt-2 w-48 origin-top-right rounded-md bg-[#17290A] shadow-lg ring-1 ring-lime-400 ring-opacity-50 focus:outline-none z-50">
                  <div className="py-1">
                    <MenuItem>
                      {({ focus }) => (
                        <button
                          onClick={() => navigate(`${baseURL}/pricing`)}
                          className={`${
                            focus ? "" : "text-lime-400"
                          } group flex w-full items-center px-4 py-2 text-sm`}
                        >
                          Get More Credits
                        </button>
                      )}
                    </MenuItem>
                    <MenuItem>
                      {({ focus }) => (
                        <button
                          onClick={handleSignOut}
                          className={`${
                            focus ? "" : "text-lime-400"
                          } group flex w-full items-center px-4 py-2 text-sm`}
                        >
                          Sign Out
                        </button>
                      )}
                    </MenuItem>
                  </div>
                </MenuItems>
              </Menu>
            </div>
          </div>
        </div>
        <section className="bg-gray-950 relative mx-4">
          <div className="mt-10 text-center flex items-center justify-between sm:text-start mx-auto sm:max-w-xl md:max-w-4xl lg:max-w-5xl px-4 py-6 sm:px-6 lg:px-8 shadow-sm">
            <h1 className="text-3xl font-bold tracking-tight text-lime-500">
              Interviews
            </h1>
            <div
              className="flex items-center gap-4 mt-2 cursor-pointer hover:opacity-70"
              onClick={() => setShowSessionModal(true)}
            >
              <h1 className="text-lime-500">Create New</h1>
              <PlusCircleIcon className="h-6 w-6 text-lime-500 cursor-pointer" />
            </div>
            {/* New Session Modal */}
            <Dialog className="relative z-50" open={showSessionModal} onClose={() => setShowSessionModal(false)}>
              <DialogBackdrop className="fixed inset-0 bg-gray-950/90" />
              <div className="fixed inset-0 flex items-center justify-center ">
                <DialogPanel className="bg-lime-950 border border-lime-500/70 rounded-b-lg max-w-lg m-2 sm:m-0  w-full mx-auto shadow-[0_0_20px] shadow-lime-400/50">
                  <DialogTitle
                    as="h2"
                    className="text-lg py-4 px-10 text-center border-b bg-gray-950 border-lime-500/40 font-bold leading-6 text-lime-500"
                  >
                    Start a New Interview Session
                  </DialogTitle>
                  <div className="px-5 pb-6 pt-4 text-lime-500 space-y-4 text-center">
                    <p className="mb-8 mt-4 text-lime-400">
                      You are about to begin a new interview session. This will deduct <span className="font-bold text-lime-400">50 credits</span> from your account. Please confirm to proceed.
                    </p>
                    <div className="mt-6 flex justify-end">
                      <button
                        onClick={() => setShowSessionModal(false)}
                        className="px-4 py-2 border border-lime-500 text-lime-400 rounded-md font-medium cursor-pointer mr-2"
                      >
                        Cancel
                      </button>
                      <button
                        className="inline-flex justify-center px-4 py-2 rounded-md text-base font-semibold text-gray-900 bg-lime-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-lime-500 cursor-pointer"
                        onClick={() => {
                          setShowSessionModal(false);
                          navigate(`${baseURL}/interview`);
                        }}
                      >
                        <span className="text-zinc-950">Start Session</span>
                      </button>
                    </div>
                  </div>
                </DialogPanel>
              </div>
            </Dialog>
          </div>
          <div
            className={`py-16 ${
              feedbackIds && feedbackIds.length > 0 ? "pt-4 pb-0 px-0" : ""
            } sm:max-w-xl md:max-w-4xl lg:max-w-5xl relative mb-10 mx-auto bg-lime-900/30 overflow-hidden rounded-3xl border border-lime-500/30`}
          >
            {feedbackIds && feedbackIds.length > 0 ? (
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-lime-500/30">
                  <thead>
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-lime-400 uppercase tracking-wider">
                        #
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-lime-400 uppercase tracking-wider">
                        Interview Name
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-lime-400 uppercase tracking-wider">
                        Created At
                      </th>
                      <th className="px-6 py-3"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-lime-500/10">
                    {feedbackIds.map((obj, index) => (
                      <tr key={index} className="bg-lime-950/70">
                        <td className="px-6 py-4 whitespace-nowrap text-lime-300">
                          {index + 1}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-lime-400">
                          General Interview {index + 1}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-white">
                          {new Date(obj.created).toLocaleString()}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <button
                            onClick={() =>
                              navigate(`${CLIENT_BASE_URL}/feedback`, {
                                state: { sessionId: obj.session_id },
                              })
                            }
                            className="px-4 py-2 border bg-gray-950 border-lime-500 text-lime-500 hover:text-gray-950 hover:bg-lime-500 transition-colors duration-100 rounded-md font-medium cursor-pointer focus:outline-none text-center"
                          >
                            Review
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="flex flex-col justify-center items-center">
                <p className="text-lime-500 text-base pb-1">
                  Nothing here... yet!
                </p>
                <p className="text-lime-500/80 text-sm pb-1">
                  Your interview goals start with one click
                </p>
                <button
                  onClick={() => {
                    setShowSessionModal(true);
                  }}
                  className="block mx-auto px-4 py-2 border mt-4 bg-gray-950 border-lime-500 text-lime-500 hover:text-gray-950 hover:bg-lime-500 transition-colors duration-100 rounded-md font-medium cursor-pointer focus:outline-none text-center"
                >
                  Start Practicing
                </button>
              </div>
            )}
          </div>
        </section>
      </div>
    </>
  );
}
export default HomePage;
