import React from "react";
import { LoaderCircle } from "lucide-react";
import img from "../assets/Logo.png";
const LoadingPage = () => {
  return (
    <section className="bg-gray-950">
      <div className="flex flex-col items-center justify-center px-6 py-8 mx-auto w-full h-screen lg:py-0">
        <div className="relative flex flex-col items-center justify-center">
          <img src={img} alt="Logo" className="mb-6 w-10 h-10 rounded-full absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2" />
          <LoaderCircle className="animate-spin h-12 w-12 text-lime-400" />
        </div>
      </div>
    </section>
  );
};

export default LoadingPage;
