import React, { useEffect, useRef, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import video from "../assets/bg-video.mp4"; // Import your video file
import { AnimatedShinyText } from "./animation/AnimatedLimeText";
import { Gem, Square, LoaderCircle } from "lucide-react";
const PricingPage = () => {
  const navigate = useNavigate();
  const videoRef = useRef(null);
  const API_BASE_URL = process.env.REACT_APP_API_BASE_URL;
  const CLIENT_BASE_URL = process.env.REACT_APP_BASE_URL || "";
  const [loadingPlan, setLoadingPlan] = useState(null);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    const handleEnded = () => {
      video.currentTime = 0;
      video.play();
    };
    video.addEventListener("ended", handleEnded);
    return () => video.removeEventListener("ended", handleEnded);
  }, []);
  const getCSRFToken = () => {
    const match = document.cookie.match(/csrf_access_token=([^;]+)/);
    return match ? match[1] : null;
  };
  const handlePlanSelect = async (planId) => {
    if (loadingPlan !== null) return; // Prevent multiple clicks
    setLoadingPlan(planId);
    if (planId === 0) {
      setLoadingPlan(null);
      const subject = encodeURIComponent("Enterprise Plan Inquiry");
      window.location.href = `mailto:support@reflectlyai.com?subject=${subject}`;
      return;
    }
    const csrfToken = getCSRFToken();
    try {
      const resp = await fetch(`${API_BASE_URL}/create_order`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-CSRF-Token": csrfToken,
        },
        credentials: "include",
        body: JSON.stringify({
          plan: planId,
        }),
      });
      if ([401, 403, 404].includes(resp.status)) {
        navigate(
          `${CLIENT_BASE_URL}/login?next=` +
            encodeURIComponent(window.location.pathname)
        );
        return;
      }

      const data = await resp.json();
      console.log("Order created successfully:", data);
      if (data.order_url) {
        window.location.href = data.order_url; // Use full redirect for PayPal
      }
      setLoadingPlan(null);
    } catch (err) {
      console.error("Error creating order:", err);
      setLoadingPlan(null);
    }
  };

  const plans = [
    {
      id: 1,
      name: "Starter Plan",
      description:
        "For students and job seekers taking their first step toward confident communication. Get essential practice and feedback to ace your next opportunity",
      value: "Value",
      price: "$6.29",
      frequency: "per week",
      features: [
        "5 ReflectlyAI Interviews",
        "Custom role-specific interviews",
        "Real-time feedback",
      ],
      buttonText: "Get Started",
    },
    {
      id: 2,
      name: "Momentum Plan",
      value: "Pro",
      highlight: true,
      price: "$13.49",
      frequency: "per month",
      description:
        "For ambitious professionals who want to level up their communication skills. Enjoy more sessions and interview modes at the best value.",
      features: [
        "10 ReflectlyAI Interviews",
        "Custom role-specific interviews",
        "Real-time feedback",
        "Access to our in-depth guides",
        "Progress tracking",
      ],
      buttonText: "Upgrade Now",
    },
    {
      id: 0,
      name: "Enterprise Plan",
      description:
        "Empower your organization with scalable, AI-driven communication training. Unlock unlimited access, team analytics, and dedicated support for lasting impact.",
      value: "Business",
      price: "Custom Pricing",
      features: [
        "Unlimited ReflectlyAI Interviews",
        "Custom role-specific interviews",
        "Dedicated account manager",
        "Advanced analytics and reporting",
        "Priority support",
      ],
      buttonText: "Contact Sales",
    },
  ];
  return (
    <div className="bg-white text-gray-900">
      <section className="bg-gray-950 relative overflow-hidden ">
        <nav className="relative w-full bg-gray-950 z-[100] py-4 border-b border-lime-400/40 shadow-[0_5px_15px] shadow-lime-400/50">
          <div className="container mx-auto px-4">
            <div className="flex items-center justify-center">
              <div className="lg:flex gap-2 p-1 rounded-full bg-lime-950">
                <Link
                  className="px-1 py-1 opacity-100 rounded-full tracking-wide bg-gradient-to-r from-lime-400 via-40% via-lime-500w to-95% to-lime-400  bg-clip-text text-lg font-extrabold text-transparent transition duration-200"
                  to={`${process.env.REACT_APP_BASE_URL}/`}
                >
                  ReflectlyAI
                </Link>
              </div>
            </div>
          </div>
        </nav>
        <div className="relative container mx-auto ">
          <div className="absolute z-30 w-full h-full bg-repeat bg-[radial-gradient(#a3e635_1px,transparent_1px)] bg-[length:25px_25px] opacity-40" />
          <div className="pt-16 pb-14 bg-gradient-to-tr from-gray-950 via-zinc-950/70 to-gray-950">
            <video
              autoPlay
              ref={videoRef}
              muted
              playsInline
              className="absolute inset-0 w-full h-1/2 object-cover z-40 blur-sm opacity-90"
              src={video}
            />
            <div className="relative z-40">
              <div className="px-1 pb-4 mx-auto text-center tracking-wide text-xl text-lime-400 shadow-text-lime font-semibold uppercase">
                Pricing
              </div>
              <h1 className="text-white text-center text-4xl md:text-6xl font-bold max-w-4xl mx-auto">
                Confident and Impactful
              </h1>
              <h1 className="text-white text-center text-4xl md:text-6xl font-bold max-w-4xl mx-auto mb-6">
                Communication
              </h1>
              <p className="text-center text-white max-w-xl mx-auto text-lg">
                Starts Here,{" "}
                <AnimatedShinyText className="text-center text-lime-400 max-w-xl mx-auto text-lg mt-12">
                  Supercharged
                </AnimatedShinyText>{" "}
                by AI
              </p>
              <div className="mb-40 text-lg text-white text-center mt-10 flex flex-col lg:flex-row justify-center items-center gap-4">
                <div className="w-[210px] text-center flex justify-center items-center gap-2 border rounded-full border-lime-400/40 px-4 py-2 bg-lime-950/20 [background:linear-gradient(45deg,theme(colors.gray.950),theme(colors.gray.950)_50%,theme(colors.lime.950))_padding-box,conic-gradient(from_var(--border-angle),theme(colors.lime.950)_80%,_theme(colors.lime.600)_86%,_theme(colors.lime.400)_90%,_theme(colors.lime.500)_94%,_theme(colors.lime.600/.48))_border-box] animate-border">
                  <span>In-depth Analysis</span>
                </div>
                <div className="w-[210px] text-center flex justify-center items-center gap-2 border rounded-full border-lime-400/40 px-4 py-2 bg-lime-950/20 [background:linear-gradient(45deg,theme(colors.gray.950),theme(colors.gray.950)_50%,theme(colors.lime.950))_padding-box,conic-gradient(from_var(--border-angle),theme(colors.lime.950)_80%,_theme(colors.lime.600)_86%,_theme(colors.lime.400)_90%,_theme(colors.lime.500)_94%,_theme(colors.lime.600/.48))_border-box] animate-border">
                  <span>Progress Tracking</span>
                </div>
                <div className="w-[210px] text-center flex justify-center items-center gap-2 border rounded-full border-lime-400/40 px-4 py-2 bg-lime-950/20 [background:linear-gradient(45deg,theme(colors.gray.950),theme(colors.gray.950)_50%,theme(colors.lime.950))_padding-box,conic-gradient(from_var(--border-angle),theme(colors.lime.950)_80%,_theme(colors.lime.600)_86%,_theme(colors.lime.400)_90%,_theme(colors.lime.500)_94%,_theme(colors.lime.600/.48))_border-box] animate-border">
                  <span>Actionable Feedback</span>
                </div>
              </div>
            </div>

            <div className="relative z-40 flex flex-col px-4 lg:flex-row justify-center gap-8 items-end mb-10 mx-auto max-w-sm lg:max-w-5xl">
              {plans.map((plan, index) => (
                <div
                  className={`${
                    plan.highlight
                      ? "px-2 pb-2 pt-4  bg-lime-500 rounded-2xl"
                      : ""
                  } basis-1/3 gray-900 h-[680px] flex flex-col`}
                >
                  {plan.highlight && (
                    <div className=" mx-auto mb-4 text-center w-fit text-lime-400 text-md bg-lime-950 px-2 py-1 rounded-full">
                      Best deal
                    </div>
                  )}
                  <div
                    key={plan.id}
                    className="flex flex-1 justify-between backdrop-blur-lg px-2 py-4 flex-col items-center bg-slate-950 rounded-lg p-8  border border-lime-400/60"
                  >
                    <div className="flex flex-col h-full justify-between mx-4 text-white">
                      <div className="w-full flex items-center justify-between my-2">
                        <div className="rounded-full bg-lime-400 p-1 md:p-2">
                          <Square className="text-gray-900 w-4 h-4 md:w-6 md:h-6" />
                        </div>
                        <span className="text-lime-400 text-sm bg-lime-950 px-2 py-1 rounded-full">
                          {plan.value}
                        </span>
                      </div>
                      <div
                        id="card-title"
                        className="text-lime-400 text-lg font-bold py-1 my-2"
                      >
                        {plan.name}
                      </div>
                      <div
                        id="card-title"
                        className="text-base tracking-tight my-2 min-h-10"
                      >
                        {plan.description}
                      </div>
                      <div className="text-4xl text-start font-bold text-white my-8 ms-2">
                        {plan.price}
                        {index !== 2 && (
                          <span className="text-sm text-gray-400">
                            {plan.frequency}
                          </span>
                        )}
                      </div>
                      <div
                        id="card-features"
                        className="text-white flex-1 flex flex-col items-start gap-2 my-4"
                      >
                        {plan.features.map((feature, idx) => (
                          <div key={idx} className="flex items-start gap-2">
                            <Gem className="text-lime-400 w-4 h-4" />
                            <span className="text-sm">{feature}</span>
                          </div>
                        ))}
                      </div>
                      <div className="flex items-center  mt-4">
                        <button
                          onClick={() => handlePlanSelect(plan.id)}
                          className="mx-auto w-full max-w-xs justify-self-center self-center justify-center px-4 py-2 shadow-sm text-base font-semibold bg-gray-950/60 rounded-full border border-lime-400/30 cursor-pointer flex items-center gap-2"
                          disabled={loadingPlan !== null}
                        >
                          {loadingPlan === plan.id ? (
                            <LoaderCircle className="animate-spin h-7 w-7 text-lime-400" />
                          ) : (
                            plan.buttonText
                          )}
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            {/* <img
                class="w-full object-cover"
                src={star1}
                alt=""
              /> */}
          </div>
        </div>
      </section>
    </div>
  );
};

export default PricingPage;
