import React, { useState } from "react";
import { LoaderCircle } from "lucide-react";
import { Link, useNavigate } from "react-router-dom";
import { motion } from "motion/react";
const RegisterPage = () => {
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: "", username: "", password: "" });
  const [msg, setMsg] = useState({ type: "", message: "" });
  const [agreed, setAgreed] = useState(false);
  const [loading, setLoading] = useState(null);
  const API_URL = process.env.REACT_APP_API_BASE_URL;
  const handleChange = (e) => {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleResendLink = async () => {
    setMsg({ type: "", message: "" });
    try {
      const res = await fetch(`${API_URL}/resend-verification`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include", // <- this is critical for cookie to be set!
        body: JSON.stringify({ email: form.email }),
      });
      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to resend verification link");
      }
      setMsg({ type: "success", message: data.msg });
    } catch (err) {
      setMsg({ type: "error", message: err.message });
    }
  };
  const handleSubmit = async (e) => {
    e.preventDefault();
    setMsg({ type: "", message: "" });
    if (loading) return;
    setLoading(true);

    if (!agreed) {
      setMsg({
        type: "error",
        message: "You must agree to the Terms and Conditions to register.",
      });
      setLoading(false);
      return;
    }

    // Validate password strength
    const isStrongPassword = (password) => {
      const regex =
        /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*#?&])[A-Za-z\d@$!%*#?&]{8,}$/;
      return regex.test(password);
    };
    // Validate email format
    const isValidEmail = (email) => {
      const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return regex.test(email);
    };
    if (!isValidEmail(form.email)) {
      setMsg({ type: "error", message: "Please enter a valid email address." });
      setLoading(null);
      return;
    }
    if (!isStrongPassword(form.password)) {
      setMsg({
        type: "error",
        message:
          "Password must be at least 8 characters long, include uppercase, lowercase, number, and special character.",
      });
      setLoading(null);
      return;
    }
    try {
      const res = await fetch(`${API_URL}/register`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include", // <- this is critical for cookie to be set!
        body: JSON.stringify(form),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Registration failed");
      }

      setMsg({ type: "success", message: data.msg });
    } catch (err) {
      setMsg({ type: "error", message: err.message });
    }
    setLoading(null);
  };

  return (
    <section className="bg-gray-950">
      <div className="flex flex-col items-center justify-center px-6 py-8 mx-auto h-screen lg:py-0">
        <Link
          className="  bg-clip-text text-2xl font-extrabold text-transparent px-1 py-1 mb-4 rounded-full tracking-wide bg-gradient-to-r from-lime-400 to-95% to-lime-500"
          to={`${process.env.REACT_APP_BASE_URL}/about`}
        >
          ReflectlyAI
        </Link>
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5 }}
          className="w-full bg-lime-950 border border-lime-500/70 rounded-b-lg mx-auto shadow-[0_0_20px] shadow-lime-400/50 md:mt-0 max-w-[400px] md:max-w-md xl:p-0"
        >
          <div className="p-6 space-y-4 md:space-y-6 sm:p-8">
            <h1 className="text-xl font-bold leading-tight tracking-tight text-center md:text-2xl text-lime-500">
              Create a new account
            </h1>
            <form onSubmit={handleSubmit} className="space-y-4 md:space-y-6">
              <div>
                <label
                  htmlFor="username"
                  className="block mt-4 mb-2 text-base font-medium text-lime-500"
                >
                  Your username
                </label>
                <input
                  type="text"
                  name="username"
                  id="username"
                  value={form.username}
                  onChange={handleChange}
                  className="bg-gray-900 border placeholder:text-lime-700 border-lime-400/30 text-lime-400 text-md rounded-md focus:outline-none focus:ring focus:ring-lime-400/70 block w-full p-2.5"
                  placeholder="Enter your username"
                  required
                />
              </div>
              <div>
                <label
                  htmlFor="email"
                  className="block mt-4 mb-2 text-base font-medium text-lime-500"
                >
                  Your email
                </label>
                <input
                  type="email"
                  name="email"
                  id="email"
                  value={form.email}
                  onChange={handleChange}
                  className="bg-gray-900 border placeholder:text-lime-700 border-lime-400/30 text-lime-400 text-md rounded-md focus:outline-none focus:ring focus:ring-lime-400/70 block w-full p-2.5"
                  placeholder="Enter your email"
                  required
                />
              </div>
              <div>
                <label
                  htmlFor="password"
                  className="block mt-4 mb-2 text-base font-medium text-lime-500"
                >
                  Password
                </label>
                <input
                  type="password"
                  name="password"
                  id="password"
                  value={form.password}
                  onChange={handleChange}
                  placeholder="•••••••••••"
                  className="bg-gray-900 border placeholder:text-lime-700 border-lime-400/30 text-lime-400 text-md rounded-md focus:outline-none focus:ring focus:ring-lime-400/70 block w-full p-2.5"
                  required
                />
              </div>
              {msg.message && (
                <p
                  className={`text-sm font-medium text-center ${
                    msg.type === "error" ? "text-red-400" : "text-lime-400"
                  }`}
                >
                  {msg.message}
                  {msg.message && msg.type === "success" && (
                    <>
                      {" "}
                      <span
                        className="font-semibold tracking-wide text-lime-400 underline cursor-pointer"
                        onClick={handleResendLink}
                      >
                        Resend link
                      </span>
                    </>
                  )}
                </p>
              )}
              <div className="flex items-center mt-2 mb-2">
                <input
                  type="checkbox"
                  id="terms"
                  checked={agreed}
                  onChange={(e) => setAgreed(e.target.checked)}
                  className="mr-2 accent-lime-500"
                  required
                />
                <label htmlFor="terms" className="text-lime-400 text-sm">
                  I agree to the
                  <Link
                    to={`${process.env.REACT_APP_BASE_URL}/terms`}
                    className="underline text-lime-400 ml-1 hover:text-lime-300"
                  >
                    Terms and Conditions
                  </Link>
                </label>
              </div>
              <button
                type="submit"
                className="w-full mt-4 px-4 py-2 border border-lime-500 text-lime-300 rounded-md font-medium cursor-pointer focus:ring-4 focus:outline-none focus:ring-lime-400/70 text-base text-center flex items-center justify-center gap-2"
                disabled={loading}
              >
                {loading ? (
                  <LoaderCircle className="animate-spin h-7 w-7 text-lime-400" />
                ) : (
                  "Sign up"
                )}
              </button>
              <p className="text-sm font-light text-lime-500">
                Already have an account?{" "}
                <Link
                  to="/login"
                  className="font-semibold tracking-wide text-lime-400 underline"
                >
                  Login
                </Link>
              </p>
            </form>
          </div>
        </motion.div>
      </div>
    </section>
  );
};

export default RegisterPage;
