import { useEffect, useState } from "react";
import { Navigate } from "react-router-dom";
import React from "react";
import LoadingPage from "../LoadingPage";
const ProtectedRoute = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(null); // null = loading
  const [user, setUser] = useState(null);
  const API_URL = process.env.REACT_APP_API_BASE_URL;
  const CLIENT_BASE_URL = process.env.REACT_APP_BASE_URL || "";
  const getCSRFToken = () => {
    const match = document.cookie.match(/csrf_access_token=([^;]+)/);
    return match ? match[1] : null;
  };
  useEffect(() => {
    const csrfToken = getCSRFToken();
    console.log("Checking authentication status with CSRF token:", csrfToken);
    fetch(`${API_URL}/me`, {
      credentials: "include",
      headers: {
        "Content-Type": "application/json",
        ...(csrfToken ? { "X-CSRF-TOKEN": csrfToken } : {}),
      },
    })
      .then(async (res) => {
        const data = await res.json();
        if (res.ok) {
          setIsAuthenticated(true);
          setUser(data);
        } else if (data.msg === "Token has expired") {
          alert("Session expired. Please log in again.");
          setIsAuthenticated(false);
        } else if (data.msg?.includes("Missing")) {
          setIsAuthenticated("about");
        } else if (data.error === "User not found") {
          setIsAuthenticated(false);
        }
      })
      .catch(() => setIsAuthenticated("about"));
    console.log(`Checking authentication status. ${isAuthenticated}`);
  }, []);
  
  if (isAuthenticated === null)
    return <LoadingPage />; // still loading
  if (isAuthenticated === "about")
    return <Navigate to={`${CLIENT_BASE_URL}/about`} replace />;
  if (!isAuthenticated)
    return <Navigate to={`${CLIENT_BASE_URL}/login`} replace />;

  return user
    ? typeof children === "function"
      ? children(user) // for render prop pattern
      : React.cloneElement(children, { user, credits: user.credits })
    : null;
};

export default ProtectedRoute;
