import React from 'react'

const FallingStar = ({ className = "", height = "h-24", gradient = "" }) => {
  return (
    <div className={`relative flex flex-col items-center justify-center z-10 ${className}`}>
      <div className={`w-px mx-auto bg-gradient-to-b ${gradient} ${height}`} />
      <div className="leading-[0px] mx-auto drop-shadow-[0_30px_100px_#d9f99d]">
        &#10022;
      </div>
    </div>
  );
};

export default FallingStar