import NotificationToast from "./NotificationToast";
import { useEffect, useRef, useState } from "react";
import Controls from "./Controls";
import UserInfoModal from "./UserInfoModal";
import { useNavigate } from "react-router-dom";
import {
  Dialog,
  DialogBackdrop,
  DialogPanel,
  DialogTitle,
} from "@headlessui/react";
import { motion } from "motion/react";

const InterviewPage = ({ user, credits }) => {
  const [sessionId, setSessionId] = useState(null);
  const audioURLRef = useRef(null);
  const audioChunksRef = useRef([]); // Store audio chunks for replay
  const [toastState, setToastState] = useState("loading");
  const [showCreditModal, setShowCreditModal] = useState(false);
  const [showUserInfoModal, setShowUserInfoModal] = useState(false);
  const navigate = useNavigate();

  const API_BASE_URL = process.env.REACT_APP_API_BASE_URL;
  const CLIENT_BASE_URL = process.env.REACT_APP_BASE_URL || "";
  const getCSRFToken = () => {
    const match = document.cookie.match(/csrf_access_token=([^;]+)/);
    return match ? match[1] : null;
  };

  // Show credit modal on mount if credits are insufficient
  useEffect(() => {
    if (typeof credits === "number" && credits < 50) {
      setShowCreditModal(true);
      setShowUserInfoModal(false);
    } else if (typeof credits === "number" && credits >= 50) {
      setShowCreditModal(false);
      setShowUserInfoModal(true);
    }
  }, [credits]);
  const startSession = async (name, jobDescription) => {
    try {
      const formData = new FormData();
      formData.append("name", name);
      formData.append("jobDescription", jobDescription);

      const csrfToken = getCSRFToken();

      const response = await fetch(`${API_BASE_URL}/start_session`, {
        method: "POST",
        body: formData,
        credentials: "include",
        headers: csrfToken ? { "X-CSRF-TOKEN": csrfToken } : {},
      });
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData?.msg || "Failed to start session");
      }

      const data = await response.json();
      console.log("Session started successfully:", data);
      setSessionId(data.session_id);
    } catch (error) {
      console.error("Failed to fetch session ID:", error);
    }
  };

  const fetchNextQuestion = async (session_id) => {
    try {
      const csrfToken = getCSRFToken();
      const response = await fetch(`${API_BASE_URL}/next_question`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(csrfToken ? { "X-CSRF-TOKEN": csrfToken } : {}),
        },
        credentials: "include",
        body: JSON.stringify({ session_id }),
      });
      if (!response.ok) throw new Error("Failed to stream audio");

      // Stream audio using MediaSource with chunk queueing
      const mediaSource = new window.MediaSource();
      const audioURL = URL.createObjectURL(mediaSource);
      audioURLRef.current = audioURL;
      audioChunksRef.current = []; // Reset chunks for new question
      const audio = new Audio(audioURL);

      setToastState("interviewer");

      mediaSource.addEventListener("sourceopen", () => {
        const sourceBuffer = mediaSource.addSourceBuffer("audio/mpeg");
        const reader = response.body.getReader();
        const chunkQueue = [];
        let isReading = true;
        let pendingEndOfStream = false;

        function processQueue() {
          if (chunkQueue.length > 0 && !sourceBuffer.updating) {
            const chunk = chunkQueue.shift();
            sourceBuffer.appendBuffer(chunk);
            audioChunksRef.current.push(chunk); // Store chunk for replay
          } else if (
            !isReading &&
            chunkQueue.length === 0 &&
            !sourceBuffer.updating &&
            mediaSource.readyState === "open"
          ) {
            mediaSource.endOfStream();
          } else if (
            !isReading &&
            chunkQueue.length === 0 &&
            sourceBuffer.updating
          ) {
            pendingEndOfStream = true;
          }
        }

        sourceBuffer.addEventListener("updateend", () => {
          if (
            pendingEndOfStream &&
            !sourceBuffer.updating &&
            mediaSource.readyState === "open"
          ) {
            mediaSource.endOfStream();
            pendingEndOfStream = false;
          } else {
            processQueue();
          }
        });

        function read() {
          reader.read().then(({ done, value }) => {
            if (done) {
              isReading = false;
              processQueue();
              return;
            }
            chunkQueue.push(value);
            processQueue();
            read();
          });
        }
        read();
      });

      audio.onended = () => setToastState("readyToRepeat");
      audio.play();
    } catch (error) {
      console.error("Failed to fetch next question:", error);
    }
  };

  const replay = () => {
    if (audioChunksRef.current.length > 0) {
      // Create a Blob from the stored chunks and play it
      const audioBlob = new Blob(audioChunksRef.current, {
        type: "audio/mpeg",
      });
      const audioURL = URL.createObjectURL(audioBlob);
      const audio = new Audio(audioURL);
      setToastState("interviewer");
      audio.addEventListener("canplaythrough", () => {
        audio.play();
      });
      audio.onended = () => {
        setToastState("readyToRepeat");
        URL.revokeObjectURL(audioURL); // Clean up
      };
    }
  };
  useEffect(() => {
    if (sessionId) {
      fetchNextQuestion(sessionId);
    }
  }, [sessionId]);
  // CreditWarningModal styled like FormModal
  const CreditWarningModal = ({ open, onClose, onBuyCredits }) => {
    if (!open) return null;
    return (
      <Dialog className="relative z-50" open={open} onClose={onClose}>
        <DialogBackdrop className="fixed inset-0 bg-gray-950/90" />
        <div className="fixed inset-0 flex items-center justify-center ">
          <DialogPanel className="bg-lime-950 border border-lime-500/70 rounded-b-lg max-w-lg w-full mx-auto shadow-[0_0_20px] shadow-lime-400/50">
            <DialogTitle
              as="h2"
              className="text-lg py-4 px-10 text-center border-b bg-gray-950 border-lime-500/40 font-bold leading-6 text-lime-500"
            >
              Not Enough Credits
            </DialogTitle>
            <motion.div
              className="px-10 pb-6 pt-4 text-lime-500 space-y-4 text-center"
              initial={{ opacity: 0 }}
              whileInView={{ opacity: 1 }}
              transition={{ duration: 0.8, ease: "easeInOut" }}
            >
              <p className="mb-4 text-lime-300">
                You need at least{" "}
                <span className="font-bold text-lime-400">50 credits</span> to
                start a new session.
              </p>
              <div className="mt-6 flex justify-center gap-4">
                <button
                  type="button"
                  onClick={onClose}
                  className="px-4 py-2 border border-lime-500 text-lime-300 rounded-md font-medium cursor-pointer"
                >
                  Close
                </button>
                <button
                  type="button"
                  onClick={onBuyCredits}
                  className="inline-flex justify-center px-4 py-2 border border-transparent rounded-md text-base font-semibold text-gray-900 bg-lime-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-lime-500 cursor-pointer"
                >
                  Buy Credits
                </button>
              </div>
            </motion.div>
          </DialogPanel>
        </div>
      </Dialog>
    );
  };

  return (
    <section className=" relative overflow-y-clip bg-gray-950">
      <CreditWarningModal
        open={showCreditModal}
        onClose={() => navigate(`${CLIENT_BASE_URL}`)}
        onBuyCredits={() => navigate(`${CLIENT_BASE_URL}/pricing`)}
      />
      {showUserInfoModal && <UserInfoModal onSubmit={startSession} />}

      <div className="absolute top-2 left-1/2 -translate-x-1/2 text-center w-full bg-white/10">
        <div className="overflow-x-auto">
          <div className="flex items-center justify-center gap-12">
            <a
              className="px-1 py-1 opacity-100 border-b-2 border-lime-400 tracking-wide bg-gradient-to-r from-lime-400 from-30% via-lime-500 to-95% to-lime-400  bg-clip-text text-lg font-bold text-transparent transition duration-200"
              href="#"
            >
              ReflectlyAI
            </a>
          </div>
        </div>
      </div>
      <NotificationToast state={toastState} onButtonClick={replay} />
      <div className="h-screen w-full flex flex-col items-center justify-center px-8 md:px-4 lg:px-0 pb-24 pt-4">
        <Controls
          toastState={toastState}
          setToastState={setToastState}
          sessionId={sessionId}
          fetchNextQuestion={fetchNextQuestion}
        />
      </div>
    </section>
  );
};

export default InterviewPage;
