import React, { useEffect } from "react";
import { ProgressCircle } from "./ProgressCircle";
import axios from "axios";
import { RotateWords } from "./animation/Text";
import { Link, useLocation, useNavigate } from "react-router-dom";
import Skeleton from "./animation/Skeleton";
import { LineChart } from "@mui/x-charts/LineChart";
import { motion } from "framer-motion";
import {
  ArrowLeftCircle,
  CircleChevronLeft,
  CircleChevronRight,
} from "lucide-react";
import AccordionElement from "./Accordion";
const chartSx = {
  ".MuiChartsGrid-line, .MuiChartsAxis-tick": {
    stroke: "#a3e63526",
    strokeWidth: 1,
  },
  ".MuiChartsAxis-line": {
    stroke: "#a3e635ff !important",
    strokeWidth: "2 !important",
  },
  ".MuiChartsAxis-tickLabel": {
    fill: "#a3e635 !important",
  },
};
const FeedbackPage = () => {
  const location = useLocation();
  const rotateWords = [
    "Hang tight! ReflectlyAI is finding its interviewer glasses!",
    "Good news: We don’t ghost. Even better news: Your feedback is on its way..",
    "Analyzing your performance like a recruiter with 3 cups of coffee...",
  ];
  const sections = [
    "Question Breakdown",
    "Detailed Analytics",
    "Final Feedback",
  ];

  const sessionId = location.state?.sessionId || null;
  const [feedback, setFeedback] = React.useState(null);
  const navigate = useNavigate();
  const API_URL = process.env.REACT_APP_API_BASE_URL;
  const CLIENT_BASE_URL = process.env.REACT_APP_BASE_URL || "";
  const getCSRFToken = () => {
    const match = document.cookie.match(/csrf_access_token=([^;]+)/);
    return match ? match[1] : null;
  };
  const placeholder_feedback = {
    strengths:
      "Interviewee demonstrated strong communication skills and confidence.",
    areas_to_improve: "Could work on pacing and reducing filler words.",
    tips: "Practice mock interviews to improve pacing and reduce filler words.",
    final_score: 85,
  };
  const getFillerFeedback = (count) => {
    if (count <= 5)
      return {
        remark: "Excellent",
        color: "bg-lime-400 shadow-[0_5px_35px] shadow-lime-400/50",
      };
    if (count <= 10) return { remark: "Good", color: "bg-lime-500" };
    if (count <= 20) return { remark: "Fair", color: "bg-yellow-400" };
    return { remark: "Needs improvement", color: "bg-red-400" };
  };
  const getWeakFeedback = (count) => {
    if (count <= 10)
      return {
        remark: "Excellent",
        color: "bg-lime-400 shadow-[0_5px_35px] shadow-lime-400/50",
      };
    if (count <= 15) return { remark: "Good", color: "bg-lime-500" };
    if (count <= 20) return { remark: "Fair", color: "bg-yellow-400" };
    return { remark: "Needs improvement", color: "bg-red-400" };
  };

  const getClarityFeedback = (clarity) => {
    if (clarity >= 8.5 && clarity <= 10)
      return {
        remark: "Excellent",
        color: "bg-lime-400 shadow-[0_5px_35px] shadow-lime-400/50",
      };
    if (clarity >= 7 && clarity < 8.5)
      return { remark: "Good", color: "bg-lime-500" };
    if (clarity >= 5 && clarity < 7)
      return { remark: "Fair", color: "bg-yellow-400" };
    return { remark: "Needs Improvement", color: "bg-red-400" };
  };

  const getVocabDiversityFeedback = (ttr) => {
    if (ttr >= 0.45 && ttr <= 0.6)
      return {
        remark: "Excellent",
        color: "bg-lime-400 shadow-[0_5px_35px] shadow-lime-400/50",
      };
    if ((ttr >= 0.4 && ttr < 0.45) || (ttr > 0.6 && ttr <= 0.7))
      return { remark: "Good", color: "bg-lime-500" };
    if ((ttr >= 0.35 && ttr < 0.4) || (ttr > 0.7 && ttr <= 0.8))
      return { remark: "Fair", color: "bg-yellow-400" };
    return { remark: "Needs Improvement", color: "bg-red-400" };
  };
  const getSentenceStarterFeedback = (count) => {
    if (count <= 5)
      return {
        remark: "Excellent",
        color: "bg-lime-400 shadow-[0_5px_35px] shadow-lime-400/50",
      };
    if (count <= 10) return { remark: "Good", color: "bg-lime-500" };
    if (count <= 20) return { remark: "Fair", color: "bg-yellow-400" };
    return { remark: "Needs improvement", color: "bg-red-400" };
  };
  const getAverageSentenceLengthFeedback = (count) => {
    if (count >= 12 && count <= 20)
      return {
        remark: "Excellent",
        color: "bg-lime-400 shadow-[0_5px_35px] shadow-lime-400/50",
      };
    if ((count >= 9 && count <= 11) || (count >= 21 && count <= 25))
      return { remark: "Good", color: "bg-lime-500" };
    if ((count >= 6 && count <= 8) || (count >= 26 && count <= 30))
      return { remark: "Fair", color: "bg-yellow-400" };
    return { remark: "Needs improvement", color: "bg-red-400" };
  };

  const [questionIdx, setQuestionIndex] = React.useState(0);
  const [sectionIdx, setSectionIndex] = React.useState(0);
  // Combines an array of dicts into a single dict, summing values for duplicate keys
  const combineDicts = (arr) => {
    return arr.reduce((acc, obj) => {
      Object.entries(obj).forEach(([key, value]) => {
        acc[key] = (acc[key] || 0) + value;
      });
      return acc;
    }, {});
  };

//   const feedback = {
//   questions: [
//     "Hello RJ! It's so great to meet you! What is your greatest strength?",
//     "Can you tell me about a time when you had to overcome a significant challenge?",
//     "Where do you see yourself in five years?"
//   ],
//   responses: [
//     "Hello! It's great to meet you too! My greatest strength is my ability to adapt quickly to new situations and challenges. I thrive in dynamic environments and enjoy learning new skills. For example, in my previous role, I was able to quickly learn a new software system that improved our team's efficiency by 20%. I believe this adaptability will be a valuable asset in this position.",
//     "In my previous role, we faced a critical deadline for a major client project, but our team was unexpectedly short-staffed. I volunteered to take on additional responsibilities and worked closely with colleagues from other departments to ensure we met our deadline. I organized daily check-ins and created a shared tracking system that improved our coordination. Despite the challenges, we delivered the project on time with excellent quality, and the client extended their contract with us.",
//     "In five years, I see myself having developed deeper expertise in this field, possibly in a senior or leadership role where I can mentor others. I'm passionate about continuous learning, so I plan to pursue additional certifications and stay current with industry trends. Ultimately, I want to be in a position where I can make significant contributions to the organization while continuing to grow professionally."
//   ],
//   filler_count: [{ um: 2, like: 1 }, { uh: 4 }, { "you know": 3 }],
//   weak_count: [{ just: 1 }, { maybe: 2 }, { "sort of": 1 }],
//   pacing_per_interval: [
//     [120, 130, 125],
//     [110, 115, 120],
//     [140, 135, 130],
//   ],
//   starter_count: [{ and: 1 }, { well: 1 }, { so: 1 }],
//   avg_sentence_length: [[14.2, 17.5, 12.8]],
//   vocab_diversity: [[0.52, 0.48, 0.55]],
//   clarity: [8.5, 9.0, 8.0],
//   pacing: [9, 8, 10],
//   pacing_variability: [7, 8, 9],
//   relevance: [
//     { score: 9, reason: "Directly answered the question." },
//     { score: 8, reason: "Mostly relevant, slight digression." },
//     { score: 10, reason: "Highly relevant and focused." },
//   ],
//   completeness: [
//     { score: 8, reason: "Good detail, could elaborate more." },
//     { score: 9, reason: "Thorough and complete." },
//     { score: 7, reason: "Missed some details." },
//   ],
//   structure: [
//     { score: 8, reason: "Clear flow, minor jumps." },
//     { score: 9, reason: "Well-structured, easy to follow." },
//     { score: 7, reason: "Somewhat scattered." },
//   ],
//   visual_frame: [
//     { score: 9, reason: "Well centered, good lighting." },
//     { score: 8, reason: "Slightly off-center." },
//     { score: 10, reason: "Excellent framing." },
//   ],
//   body_language: [
//     { score: 8, reason: "Confident, open posture." },
//     { score: 7, reason: "Some nervous gestures." },
//     { score: 9, reason: "Relaxed and engaging." },
//   ],
//   facial_expressions: [
//     { score: 9, reason: "Warm, natural smile." },
//     { score: 8, reason: "Neutral, but pleasant." },
//     { score: 10, reason: "Very engaging expression." },
//   ],
//   strengths: "You demonstrated excellent communication skills with clear articulation and good pacing. Your responses were well-structured with a good balance of specific examples and general statements. Your body language was confident and engaging, which reinforced your message effectively.",
//   areas_to_improve: "You could reduce your use of filler words like 'um' and 'uh' which appeared several times throughout your responses. In some answers, you could provide more specific details to strengthen your examples. Your pacing occasionally became too rapid when discussing complex topics.",
//   tips: "Practice pausing instead of using filler words when gathering your thoughts. Prepare more detailed examples for common interview questions. Record yourself speaking to identify and work on your pacing patterns. Consider using the STAR method (Situation, Task, Action, Result) to structure your responses to behavioral questions.",
//   final_score: 85
// };
  const sumDictValuesinArrayOfDicts = (dict) => {
    // dict is an array of objects, e.g. [{ um: 2, like: 1 }, { uh: 4 }, { "you know": 3 }]
    let sum = 0;
    dict.forEach((item) => {
      Object.values(item).forEach((value) => {
        sum += value;
      });
    });
    return sum;
  };
  useEffect(() => {
    const pollForFeedback = async () => {
      if (!sessionId) {
        console.error("Session ID is not available.");
        navigate(`${CLIENT_BASE_URL}/`);
        return;
      }
      if (feedback) {
        return;
      }
      const csrfToken = getCSRFToken();
      try {
        const res = await fetch(`${API_URL}/get_feedback`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...(csrfToken ? { "X-CSRF-TOKEN": csrfToken } : {}),
          },
          credentials: "include",
          body: JSON.stringify({ session_id: sessionId })
        });
        const data = await res.json();
        // Handle missing cookie or unauthorized
        if (res.status === 401 || (data.msg && data.msg.includes("cookie"))) {
          console.error("Not authenticated. Redirecting to login.");
          navigate(`${CLIENT_BASE_URL}/login`, { replace: true, state: { next: "/feedback" } });
          return;
        }
        if (data && data.final_score !== undefined) {
          setFeedback(data);
        } else {
          setTimeout(pollForFeedback, 5000); // Retry in 5s
        }
      } catch (err) {
        console.error("❌ Error fetching feedback:", err);
        // Only retry on network errors, not on auth errors
        setTimeout(pollForFeedback, 5000);
      }
    };
    pollForFeedback();
  }, [sessionId]);

  return (
    <div className="bg-white text-gray-900">
      <section className="bg-gray-950  min-h-screen relative overflow-hidden flex flex-col items-center justify-center">
        <div className="py-5 w-full ">
          <div className="mx-auto px-4 w-full">
            <div className="px-3 mb-1 text-lime-400 text-center font-light tracking-tight text-4xl sm:text-5xl md:text-6xl md:leading-[4rem] mx-auto text-shadow-[0_0_30px_#a3e635]">
              Feedback
            </div>
            <div className="flex items-center justify-center">
              <div
                className={
                  "rounded-full w-full h-[1px] bg-gradient-to-r via-lime-700 from-lime-900 to-lime-500"
                }
              ></div>

              <div className="lg:flex rounded-full  bg-gray-950/50 z-50">
                <div className="p-1 px-2 opacity-100 border border-lime-400/70 rounded-full tracking-wide bg-gradient-to-r from-lime-400 via-40% via-lime-500 to-95% to-lime-400 bg-clip-text text-md font-extrabold text-transparent transition duration-200">
                  ReflectlyAI
                </div>
              </div>

              <div
                className={
                  "rounded-full w-full h-[1px] bg-gradient-to-l via-lime-700 from-lime-900 to-lime-500"
                }
              ></div>
            </div>
          </div>
        </div>
        {feedback ? (
          <>
        <div className="flex-1 container flex justify-between  max-w-xl bg-gray-950 md:max-w-2xl lg:max-w-4xl mx-2 sm:mx-auto relative z-30">
          {sections.map((section, index) => (
            <div
              key={index}
              className={`relative basis-1/3 text-lime-400 cursor-pointer  text-center px-2 py-2 rounded-t-lg text-lg md:text-xl font-light tracking-tight ${
                sectionIdx === index
                  ? "font-bold text-white border-t border-l border-r border-lime-400/80 bg-lime-950/40 z-10"
                  : " text-opacity-40 hover:text-lime-200/60"
              }`}
              onClick={() => setSectionIndex(index)}
            >
              {sectionIdx === index && (
                <div className="absolute left-0 -bottom-1 h-2 w-full bg-[#0C160D] rounded-t-lg"></div>
              )}
              {section}
            </div>
          ))}
        </div>
        <div className="relative container border border-lime-400/80 shadow-[0_5px_10px] rounded-b-lg shadow-lime-400/50 flex flex-col justify-center gap-2 items-center max-w-xl bg-lime-950/40 md:max-w-2xl lg:max-w-4xl mx-2 sm:mx-auto mb-4 px-4">
          {/* Questionwise analysis */}
          <div className={`${sectionIdx === 0 ? "block" : "hidden"} w-full`}>
            <div className="flex justify-between items-center max-w-sm mx-auto mb-6 mt-4 gap-4">
              <CircleChevronLeft
                onClick={() => setQuestionIndex(Math.max(questionIdx - 1, 0))}
                className={`bg-lime-400 ${
                  questionIdx === 0 ? "opacity-20 pointer-events-none" : ""
                } cursor-pointer text-lime-950 rounded-full border-none w-6 h-6`}
              />
              <div className="text-lime-400 text-lg font-light tracking-normal ">
                Question {questionIdx + 1} of {feedback.questions.length}
              </div>
              <CircleChevronRight
                onClick={() =>
                  setQuestionIndex(Math.min(questionIdx + 1, feedback.questions.length - 1))
                }
                className={`bg-lime-400 ${
                  questionIdx === feedback.questions.length - 1
                    ? "opacity-20 pointer-events-none"
                    : ""
                } cursor-pointer text-gray-950 rounded-full border-none w-6 h-6`}
              />
            </div>
            <p className="text-gray-300 text-lg font-light tracking-normal my-1">
              <span className="text-lime-400 font-bold">Question: </span>
              {feedback.questions[questionIdx]}
            </p>
            <p className="text-gray-300 text-lg font-light tracking-normal my-1">
              <span className="text-lime-400 font-bold">Response: </span>
              {feedback.responses[questionIdx]}
            </p>
            <div className="text-lime-400 text-center text-xl font-medium tracking-normal my-1">
              Response evaluation
            </div>
            <AccordionElement title={"Relevance"} index={0} length={1}>
              <div className="text-gray-300 text-base font-light tracking-normal my-1">
                <p className="text-lime-400">
                  Score:{" "}
                  <span className="text-white">
                    {feedback.relevance[questionIdx].score}
                  </span>
                </p>
                <p className="text-lime-400">
                  Feedback:{" "}
                  <span className="text-white">
                    {feedback.relevance[questionIdx].reason}
                  </span>
                </p>
              </div>
            </AccordionElement>
            <AccordionElement title={"Completeness"} index={0} length={1}>
              <div className="text-gray-300 text-base font-light tracking-normal my-1">
                <p className="text-lime-400">
                  Score:{" "}
                  <span className="text-white">
                    {feedback.completeness[questionIdx].score}
                  </span>
                </p>
                <p className="text-lime-400">
                  Feedback:{" "}
                  <span className="text-white">
                    {feedback.completeness[questionIdx].reason}
                  </span>
                </p>
              </div>
            </AccordionElement>
            <AccordionElement title={"Structure"} index={0} length={1}>
              <div className="text-gray-300 text-base font-light tracking-normal my-1">
                <p className="text-lime-400">
                  Score:{" "}
                  <span className="text-white">
                    {feedback.structure[questionIdx].score}
                  </span>
                </p>
                <p className="text-lime-400">
                  Feedback:{" "}
                  <span className="text-white">
                    {feedback.structure[questionIdx].reason}
                  </span>
                </p>
              </div>
            </AccordionElement>
            <div className="text-lime-400 text-center text-xl font-medium tracking-normal my-1 mt-2">
              Visual evaluation
            </div>
            <AccordionElement title={"Framing"} index={0} length={1}>
              <div className="text-gray-300 text-base font-light tracking-normal my-1">
                <p className="text-lime-400">
                  Score:{" "}
                  <span className="text-white">
                    {feedback.visual_frame[questionIdx].score}
                  </span>
                </p>
                <p className="text-lime-400">
                  Feedback:{" "}
                  <span className="text-white">
                    {feedback.visual_frame[questionIdx].reason}
                  </span>
                </p>
              </div>
            </AccordionElement>
            <AccordionElement title={"Body language"} index={0} length={1}>
              <div className="text-gray-300 text-base font-light tracking-normal my-1">
                <p className="text-lime-400">
                  Score:{" "}
                  <span className="text-white">
                    {feedback.body_language[questionIdx].score}
                  </span>
                </p>
                <p className="text-lime-400">
                  Feedback:{" "}
                  <span className="text-white">
                    {feedback.body_language[questionIdx].reason}
                  </span>
                </p>
              </div>
            </AccordionElement>
            <AccordionElement title={"Facial engagement"} index={0} length={1}>
              <div className="text-gray-300 text-base font-light tracking-normal my-1">
                <p className="text-lime-400">
                  Score:{" "}
                  <span className="text-white">
                    {feedback.facial_expressions[questionIdx].score}
                  </span>
                </p>
                <p className="text-lime-400">
                  Feedback:{" "}
                  <span className="text-white">
                    {feedback.facial_expressions[questionIdx].reason}
                  </span>
                </p>
              </div>
            </AccordionElement>
          </div>

          {/* Questionwise analysis-end */}

          {/* Analytics */}
          <div className={`${sectionIdx === 1 ? "block" : "hidden"} w-full`}>
            <div className="text-lime-400 text-center text-xl font-medium tracking-normal my-1 mt-8">
              Response Quality Evaluation
            </div>
            {(() => {
              let fillerCnt = sumDictValuesinArrayOfDicts(
                feedback.filler_count
              );
              const fillerFeedback = getFillerFeedback(fillerCnt);
              const getCombinedDict = combineDicts(feedback.filler_count);

              return (
                <AccordionElement title="Filler words">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400">
                      Count:{" "}
                      <span className="text-white text-sm">{fillerCnt}</span>
                    </p>
                    <p className="text-white text-sm flex flex-wrap justify-start items-center gap-2 my-1">
                      {Object.entries(getCombinedDict).map(([key, value]) => (
                        <span
                          key={key}
                          className="bg-lime-800 px-2 font-medium rounded-full"
                        >
                          {key}: {value}
                        </span>
                      ))}
                    </p>
                    <p className="text-lime-400">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${fillerFeedback.color}`}
                      >
                        {fillerFeedback.remark}
                      </span>
                    </p>
                    <p className="text-white text-base my-1">
                      Filler words (like "um", "uh", "like", "you know") reduce
                      the clarity of your message and can make it harder for
                      your audience to follow your ideas. Reducing fillers helps
                      you sound more confident and professional.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
            {(() => {
              let weakCnt = sumDictValuesinArrayOfDicts(
                feedback.weak_count
              );
              const weakFeedback = getWeakFeedback(weakCnt);
              const getCombinedDict = combineDicts(feedback.weak_count);
              return (
                <AccordionElement title="Weak words">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400">
                      Count:{" "}
                      <span className="text-white text-sm">{weakCnt}</span>
                    </p>
                    <p className="text-white text-sm flex flex-wrap justify-start items-center gap-2 my-1">
                      {Object.entries(getCombinedDict).map(([key, value]) => (
                        <span
                          key={key}
                          className="bg-lime-800 px-2 font-medium rounded-full"
                        >
                          {key}: {value}
                        </span>
                      ))}
                    </p>
                    <p className="text-lime-400 my-1">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${weakFeedback.color}`}
                      >
                        {weakFeedback.remark}
                      </span>
                    </p>
                    <p className="text-white text-base my-1">
                      Weak words (like "very", "really", "quite", "just") can
                      undermine your message and make you sound less confident.
                      Try to use more assertive language to convey your ideas
                      more powerfully.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
            {(() => {
              let starter_count = sumDictValuesinArrayOfDicts(
                feedback.starter_count
              );
              const sentenceStarterFeedback =
                getSentenceStarterFeedback(starter_count);
              const getCombinedDict = combineDicts(feedback.starter_count);
              return (
                <AccordionElement title="Unnecessary sentence starters">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400">
                      Count:{" "}
                      <span className="text-white text-sm">
                        {starter_count}
                      </span>
                    </p>
                    <p className="text-white text-sm flex flex-wrap justify-start items-center gap-2 my-1">
                      {Object.entries(getCombinedDict).map(([key, value]) => (
                        <span
                          key={key}
                          className="bg-lime-800 px-2 font-medium rounded-full"
                        >
                          {key}: {value}
                        </span>
                      ))}
                    </p>
                    <p className="text-lime-400">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${sentenceStarterFeedback.color}`}
                      >
                        {sentenceStarterFeedback.remark}
                      </span>
                    </p>
                    <p className="text-white text-base my-1">
                      Starting sentences with words like "and", "but", or "so"
                      can make your speech sound informal or disjointed. Try to
                      begin sentences with clear, direct statements for a more
                      polished delivery. The lesser the count, the better.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
            {(() => {
              let sum = 0;
              feedback.avg_sentence_length.forEach((arr) => {
                arr.forEach((length) => {
                  sum += length;
                });
              });
              let length = 0;
              feedback.avg_sentence_length.forEach((arr) => {
                length += arr.length;
              });
              let avgSentenceLength = Number(sum / length).toFixed(1);
              let arr = [];
              feedback.avg_sentence_length.forEach((inn) => {
                arr = arr.concat(inn);
              });
              const averageSentenceLengthFeedback =
                getAverageSentenceLengthFeedback(avgSentenceLength);
              return (
                <AccordionElement title="Sentence Length">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400 my-1">
                      Value:{" "}
                      <span className="text-white text-sm">
                        {avgSentenceLength}
                      </span>
                    </p>
                    <p className="text-lime-400 my-1">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${averageSentenceLengthFeedback.color}`}
                      >
                        {averageSentenceLengthFeedback.remark}
                      </span>
                    </p>
                    <div className="text-lime-400 my-1">
                      {arr && (
                        <LineChart
                          xAxis={[
                            {
                              data: arr.map((_, i) => i + 1),
                              min: 1,
                              max: arr.length,
                              tickMinStep: 1, // Ensures ticks are at least 1 apart
                            },
                          ]}
                          series={[{ data: arr }]}
                          width={400}
                          height={300}
                          xAxisLabel="Sentence Number"
                          yAxisLabel="Average Sentence Length"
                          grid={{
                            vertical: true,
                            horizontal: true,
                          }}
                          colors={["#a3e635"]}
                          sx={chartSx}
                        />
                      )}
                      <div className="ps-10 text-lime-400 text-center text-base font-medium tracking-normal -mt-3 mb-4">
                        Segment number vs Average Sentence Length
                      </div>
                    </div>
                    <p className="text-white text-base my-1">
                      Clear communication often uses sentences that are neither
                      too short nor too long. Aim for sentences between 12 and
                      20 words to keep your answers concise and easy to follow.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
            {(() => {
              //Windowed ttr
              let sum = 0;
              feedback.vocab_diversity.forEach((arr) => {
                arr.forEach((length) => {
                  sum += length;
                });
              });
              let length = feedback.vocab_diversity.reduce(
                (acc, curr) => acc + curr.length,
                0
              );
              let avgVocabDiversity = Number((sum / length).toFixed(2));
              let arr = [];
              feedback.vocab_diversity.forEach((inn) => {
                arr = arr.concat(inn);
              });
              const vocabDiversityFeedback =
                getVocabDiversityFeedback(avgVocabDiversity);
              return (
                <AccordionElement title="Vocabulary Diversity">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400 my-1">
                      Value:{" "}
                      <span className="text-white text-sm">
                        {avgVocabDiversity}
                      </span>
                    </p>
                    <p className="text-lime-400 my-1">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${vocabDiversityFeedback.color}`}
                      >
                        {vocabDiversityFeedback.remark}
                      </span>
                    </p>
                    <div className="text-lime-400 my-1">
                      {arr && (
                        <LineChart
                          xAxis={[
                            {
                              data: arr.map((_, i) => i + 1),
                              min: 1,
                              max: arr.length,
                              tickMinStep: 1, // Ensures ticks are at least 1 apart
                            },
                          ]}
                          series={[{ data: arr }]}
                          width={400}
                          height={300}
                          grid={{
                            vertical: true,
                            horizontal: true,
                          }}
                          colors={["#a3e635"]}
                          sx={chartSx}
                        />
                      )}
                      <div className="ps-10 text-lime-400 text-center text-base font-medium tracking-normal -mt-3 mb-4">
                        Segment number vs Vocabulary diversity score
                      </div>
                    </div>
                    <p className="text-white text-base my-1">
                      A varied vocabulary keeps your answers interesting and
                      shows depth of knowledge. Try to use a range of words, but
                      avoid using complex words just for the sake of it. Output
                      score of 0.4 to 0.6 from our algorithm is the ideal range.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
            <div className="text-lime-400 text-center text-xl font-medium tracking-normal my-1 mt-8">
              Vocal Image Evaluation
            </div>
            {(() => {
              //Clarity
              let sum = 0;
              feedback.clarity.forEach((clarity) => {
                sum += clarity;
              });
              let avgClarity = Number(
                (sum / feedback.clarity.length).toFixed(1)
              );
              const clarityFeedback = getClarityFeedback(avgClarity);
              let arr = feedback.clarity;
              return (
                <AccordionElement title="Clarity">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400 my-1">
                      Value:{" "}
                      <span className="text-white text-sm">{avgClarity}</span>
                    </p>
                    <p className="text-lime-400 my-1">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${clarityFeedback.color}`}
                      >
                        {clarityFeedback.remark}
                      </span>
                    </p>
                    <div className="text-lime-400 my-1">
                      {arr && (
                        <LineChart
                          xAxis={[
                            {
                              data: arr.map((_, i) => i + 1),
                              min: 1,
                              max: arr.length,
                              tickMinStep: 1, // Ensures ticks are at least 1 apart
                            },
                          ]}
                          series={[{ data: arr }]}
                          width={400}
                          height={300}
                          grid={{
                            vertical: true,
                            horizontal: true,
                          }}
                          colors={["#a3e635"]}
                          sx={chartSx}
                        />
                      )}
                      <div className="ps-10 text-lime-400 text-center text-base font-medium tracking-normal -mt-3 mb-4">
                        Question number vs Clarity score
                      </div>
                    </div>
                    <p className="text-white text-base my-1">
                      Clarity is essential for effective communication. Speaking
                      clearly and in a smooth flow helps your audience
                      understand and remember your message.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
            {(() => {
              //Pacing and Variability
              let sum = 0;
              feedback.pacing.forEach((val) => {
                sum += val;
              });
              let pacingAvg = Number(
                (sum / feedback.pacing.length).toFixed(1)
              );
              sum = 0;
              feedback.pacing_variability.forEach((val) => {
                sum += val;
              });
              let pacingVarAvg = Number(
                (sum / feedback.pacing_variability.length).toFixed(1)
              );
              let arr = [];
              feedback.pacing_per_interval.forEach((inn) => {
                arr = arr.concat(inn);
              });
              const pacingFeedback = getClarityFeedback(pacingAvg);
              return (
                <AccordionElement title="Pacing and Variability">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400 my-1">
                      Pacing Score:{" "}
                      <span className="text-white text-sm">{pacingAvg}</span>
                    </p>
                    <p className="text-lime-400 my-1">
                      Pacing Variability Score:{" "}
                      <span className="text-white text-sm">{pacingVarAvg}</span>
                    </p>
                    <p className="text-lime-400 my-1">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${pacingFeedback.color}`}
                      >
                        {pacingFeedback.remark}
                      </span>
                    </p>
                    <div className="text-lime-400 my-1">
                      {arr && (
                        <LineChart
                          xAxis={[
                            {
                              data: arr.map((_, i) => i + 1),
                              min: 1,
                              max: arr.length,
                              tickMinStep: 1, // Ensures ticks are at least 1 apart
                            },
                          ]}
                          series={[{ data: arr }]}
                          width={400}
                          height={300}
                          grid={{
                            vertical: true,
                            horizontal: true,
                          }}
                          colors={["#a3e635"]}
                          sx={chartSx}
                        />
                      )}
                      <div className="ps-10 text-lime-400 text-center text-base font-medium tracking-normal -mt-3 mb-4">
                        Interval number vs WPM
                      </div>
                    </div>
                    <p className="text-white text-base my-1">
                      Good pacing keeps your audience engaged. Speaking too
                      quickly can make it hard to follow, while speaking too
                      slowly can lose attention. Moreover, varying your pacing
                      appropriately adds interest and emphasis to your speech.
                      Too little variation can sound monotonous, while too much
                      can be distracting. Strive for a balance that matches your
                      message.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
            <div className="text-lime-400 text-center text-xl font-medium tracking-normal my-1 mt-8">
              Visual Image Evaluation
            </div>
            {(() => {
              //Pacing and Variability
              let sum = 0;
              feedback.visual_frame.forEach((val) => {
                sum += val.score;
              });
              let visualFrameAvg = Number(
                (sum / feedback.visual_frame.length).toFixed(1)
              );
              sum = 0;
              let arr = [];
              feedback.visual_frame.forEach((inn) => {
                arr.push(inn.score);
              });
              const visualFrameFeedback = getClarityFeedback(visualFrameAvg);
              return (
                <AccordionElement title="Frame">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400 my-1">
                      Frame Score:{" "}
                      <span className="text-white text-sm">
                        {visualFrameAvg}
                      </span>
                    </p>
                    <p className="text-lime-400 my-1">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${visualFrameFeedback.color}`}
                      >
                        {visualFrameFeedback.remark}
                      </span>
                    </p>
                    <div className="text-lime-400 my-1">
                      {arr && (
                        <LineChart
                          xAxis={[
                            {
                              data: arr.map((_, i) => i + 1),
                              min: 1,
                              max: arr.length,
                              tickMinStep: 1, // Ensures ticks are at least 1 apart
                            },
                          ]}
                          series={[{ data: arr }]}
                          width={400}
                          height={300}
                          grid={{
                            vertical: true,
                            horizontal: true,
                          }}
                          colors={["#a3e635"]}
                          sx={chartSx}
                        />
                      )}
                      <div className="ps-10 text-lime-400 text-center text-base font-medium tracking-normal -mt-3 mb-4">
                        Segment number vs Frame score
                      </div>
                    </div>
                    <p className="text-white text-base my-1">
                      Good visual framing ensures you are well-centered, with
                      appropriate headroom and lighting. Proper framing helps
                      you appear more professional and keeps the focus on you,
                      making your communication more engaging and effective.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
            {(() => {
              //body_language
              let sum = 0;
              feedback.body_language.forEach((val) => {
                sum += val.score;
              });
              let bodyLanguageAvg = Number(
                (sum / feedback.body_language.length).toFixed(1)
              );
              sum = 0;
              let arr = [];
              feedback.body_language.forEach((inn) => {
                arr.push(inn.score);
              });
              const bodyLanguageFeedback = getClarityFeedback(bodyLanguageAvg);
              return (
                <AccordionElement title="Body Language">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400 my-1">
                      Body Language Score:{" "}
                      <span className="text-white text-sm">
                        {bodyLanguageAvg}
                      </span>
                    </p>
                    <p className="text-lime-400 my-1">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${bodyLanguageFeedback.color}`}
                      >
                        {bodyLanguageFeedback.remark}
                      </span>
                    </p>
                    <div className="text-lime-400 my-1">
                      {arr && (
                        <LineChart
                          xAxis={[
                            {
                              data: arr.map((_, i) => i + 1),
                              min: 1,
                              max: arr.length,
                              tickMinStep: 1, // Ensures ticks are at least 1 apart
                            },
                          ]}
                          series={[{ data: arr }]}
                          width={400}
                          height={300}
                          grid={{
                            vertical: true,
                            horizontal: true,
                          }}
                          colors={["#a3e635"]}
                          sx={chartSx}
                        />
                      )}
                      <div className="ps-10 text-lime-400 text-center text-base font-medium tracking-normal -mt-3 mb-4">
                        Segment number vs Body language score
                      </div>
                    </div>
                    <p className="text-white text-base my-1">
                      Confident, open body language involving upright posture,
                      hand gestures etc. conveys assurance and helps build
                      rapport with your audience. Avoid nervous gestures or
                      closed postures, and use natural movements to emphasize
                      your points and appear more engaging.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
            {(() => {
              //Facial expressions
              let sum = 0;
              feedback.facial_expressions.forEach((val) => {
                sum += val.score;
              });
              let facialExpressionsAvg = Number(
                (sum / feedback.facial_expressions.length).toFixed(1)
              );
              sum = 0;
              let arr = [];
              feedback.facial_expressions.forEach((inn) => {
                arr.push(inn.score);
              });
              const facialExpressionsFeedback =
                getClarityFeedback(facialExpressionsAvg);
              return (
                <AccordionElement title="Facial engagement">
                  <div className="text-gray-300 text-base font-light tracking-normal my-1">
                    <p className="text-lime-400 my-1">
                      Facial Engagement Score:{" "}
                      <span className="text-white text-sm">
                        {facialExpressionsAvg}
                      </span>
                    </p>
                    <p className="text-lime-400 my-1">
                      Remark:{" "}
                      <span
                        className={`text-gray-950 px-1  text-sm font-semibold rounded-full ${facialExpressionsFeedback.color}`}
                      >
                        {facialExpressionsFeedback.remark}
                      </span>
                    </p>
                    <div className="text-lime-400 my-1">
                      {arr && (
                        <LineChart
                          xAxis={[
                            {
                              data: arr.map((_, i) => i + 1),
                              min: 1,
                              max: arr.length,
                              tickMinStep: 1, // Ensures ticks are at least 1 apart
                            },
                          ]}
                          series={[{ data: arr }]}
                          width={400}
                          height={300}
                          grid={{
                            vertical: true,
                            horizontal: true,
                          }}
                          colors={["#a3e635"]}
                          sx={chartSx}
                        />
                      )}
                      <div className="ps-10 text-lime-400 text-center text-base font-medium tracking-normal -mt-3 mb-4">
                        Segment number vs Facial engagement score
                      </div>
                    </div>
                    <p className="text-white text-base my-1">
                      Expressive facial engagement, such as smiling and
                      maintaining a pleasant expression, makes you appear
                      relaxed and interested. It helps your audience
                      connect with you and keeps their attention throughout your
                      response.
                    </p>
                  </div>
                </AccordionElement>
              );
            })()}
          </div>
          {/* Analytics end */}
          {/* Final Feedback */}
          <div className={`${sectionIdx === 2 ? "block" : "hidden"} w-full`}>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.8 }}
            >
              <div className="container max-w-xl md:max-w-2xl lg:max-w-4xl mx-auto px-4 py-4 flex flex-col items-center justify-center">
                <ProgressCircle
                  value={feedback ? feedback.final_score : 0}
                  max={100}
                  radius={100}
                  strokeWidth={10}
                ></ProgressCircle>
              </div>
              <div className="container  max-w-2xl lg:max-w-4xl mx-auto px-4 py-4">
                <div className="text-lime-400 text-start font-light tracking-tight text-3xl sm:text-4xl md:text-5xl md:leading-[4rem] mx-auto ">
                  Strengths
                </div>
                <p className="text-white mx-auto text-lg mt-4 text-justify">
                  {feedback ? feedback.strengths : "Loading strengths..."}
                </p>
                <div
                  className={"rounded-full w-full h-[1px] my-6 bg-zinc-700"}
                />
                <div className="text-lime-400 text-start font-light tracking-tight text-3xl sm:text-4xl md:text-5xl md:leading-[4rem] mx-auto">
                  Areas for Improvement
                </div>
                <p className="text-white mx-auto text-lg mt-4 text-justify">
                  {feedback
                    ? feedback.areas_to_improve
                    : "Loading areas for improvement..."}
                </p>
                <div
                  className={"rounded-full w-full h-[1px] my-6 bg-zinc-700"}
                />
                <div className="text-lime-400 text-start font-light tracking-tight text-3xl sm:text-4xl md:text-5xl md:leading-[4rem] mx-auto">
                  Final Tips
                </div>
                <p className="text-white mx-auto text-lg mt-4 text-justify">
                  {feedback ? feedback.tips : "Loading final tips..."}
                </p>
              </div>
              <div className="flex flex-col mx-auto md:max-w-2xl lg:max-w-4xl relative items-center justify-center mt-8 mb-2">
                <div className="flex items-center w-full mb-4 justify-center">
                  <div
                    className={
                      "rounded-full w-full h-[1px] bg-gradient-to-r via-lime-700 from-lime-900 to-lime-500"
                    }
                  ></div>
                  <span className="text-lime-400 text-2xl font-bold">
                    &#10022;
                  </span>
                  <div
                    className={
                      "rounded-full w-full h-[1px] bg-gradient-to-l via-lime-700 from-lime-900 to-lime-500"
                    }
                  ></div>
                </div>
                <p className="text-center text-white max-w-xl mx-auto text-lg font-bold">
                  <span className="font-extrabold text-3xl text-lime-400">
                    &ldquo;{" "}
                  </span>
                  Great job! Congratulations on completing the interview. Keep
                  pushing forward and never stop believing in yourself!
                  <span className="font-extrabold text-3xl text-lime-400">
                    {" "}
                    &rdquo;
                  </span>
                </p>
                <div className="flex items-center w-full mb-4 justify-center mt-4">
                  <div
                    className={
                      "rounded-full w-full h-[1px] bg-gradient-to-r via-lime-700 from-lime-900 to-lime-500"
                    }
                  ></div>
                  <span className="text-lime-400 text-2xl font-bold">
                    &#10022;
                  </span>
                  <div
                    className={
                      "rounded-full w-full h-[1px] bg-gradient-to-l via-lime-700 from-lime-900 to-lime-500"
                    }
                  ></div>
                </div>
              </div>
              <div class="mb-8 text-center mt-4">
                <div
                  class="group relative inline-block p-0.5 font-semibold overflow-hidden rounded-full"
                  href="#"
                >
                  <div class="absolute inset-0 bg-gradient-to-b from-white to-gray-500 group-focus:to-white opacity-40 group-focus:opacity-20 rounded-full"></div>
                  <div class="relative z-50 flex items-center py-2 px-4 text-gray-900 bg-lime-500 group-hover:opacity-80 group-focus:opacity-80 rounded-full transition duration-200">
                    <Link
                      to={"/interview"}
                    >
                      Interview Again
                    </Link>
                  </div>
                </div>
              </div>
            </motion.div>
          </div>
          {/* Final feedback end */}
        </div></>) : (<div className="flex-1 flex flex-col px-4 my-4 gap-10 justify-center items-center">
            <Skeleton />
            <RotateWords words={rotateWords} />
            <Skeleton isReversed={true} />
          </div>)}
      </section>  
    </div>
  );
};
{
  /* <div className="flex flex-col mt-10 my-4 gap-10 justify-center items-center">
            <Skeleton />
            <RotateWords words={rotateWords} />
            <Skeleton isReversed={true} />
          </div> */
}
export default FeedbackPage;
